import React, { useState } from 'react';
import {
  Box,
  Drawer,
  AppBar,
  Toolbar,
  List,
  Typography,
  Divider,
  IconButton,
  ListItem,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Menu,
  MenuItem,
  Alert,
} from '@mui/material';
import {
  Menu as MenuIcon,
  AccountCircle,
  People,
  Work,
  Event,
  AttachMoney,
  Assignment,
  Receipt,
  Business,
  Person,
  Assessment,
  BarChart,
} from '@mui/icons-material';
import { useAuth } from '../contexts/AuthContext';
import { useCompanyFilter } from '../contexts/CompanyFilterContext';
import CompanyFilter from './CompanyFilter';
import { useNavigate, useLocation } from 'react-router-dom';

const drawerWidth = 240;

interface AppLayoutProps {
  children: React.ReactNode;
}

const menuItems = [
  { text: 'Employee Information', icon: <People />, path: '/employees', permission: 'employee:view', section: 'Operations' },
  { text: 'Employment Management', icon: <Work />, path: '/employment', permission: 'employment:view', section: 'Operations' },
  { text: 'Salary Management', icon: <AttachMoney />, path: '/salary', permission: 'salary_history:view', section: 'Operations' },
  { text: 'Leave Dashboard', icon: <Event />, path: '/leaves', permission: 'leave:manage', section: 'Operations' },
  { text: 'Work Permit Management', icon: <Assignment />, path: '/work-permits', permission: 'work_permit:manage', section: 'Operations' },
  { text: 'Expense Reimbursement', icon: <Receipt />, path: '/expenses', permission: 'expense:manage', section: 'Operations' },
  { text: 'HR Reports', icon: <BarChart />, path: '/reports', permission: 'report:view', section: 'Reports & Analytics' },
  { text: 'Company Management', icon: <Business />, path: '/companies', permission: 'company:manage', section: 'System Management' },
  { text: 'User Management', icon: <Person />, path: '/users', permission: 'user:view', section: 'System Management' },
  { text: 'Audit Report', icon: <Assessment />, path: '/audit', permission: 'audit:view', section: 'System Management' },
];

export const AppLayout: React.FC<AppLayoutProps> = ({ children }) => {
  const [mobileOpen, setMobileOpen] = useState(false);
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  
  const { user, logout, hasPermission } = useAuth();
  const { selectedCompanyId, setSelectedCompanyId, selectedCompany } = useCompanyFilter();
  const navigate = useNavigate();
  const location = useLocation();

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const handleMenu = (event: React.MouseEvent<HTMLElement>) => {
    setAnchorEl(event.currentTarget);
  };

  const handleClose = () => {
    setAnchorEl(null);
  };

  const handleLogout = () => {
    logout();
    handleClose();
  };

  const handleChangePassword = () => {
    navigate('/change-password');
    handleClose();
  };

  // Filter menu items based on permissions
  const accessibleItems = menuItems.filter(item => hasPermission(item.permission));
  
  // Group items by section
  const groupedItems = accessibleItems.reduce((acc, item) => {
    if (!acc[item.section]) {
      acc[item.section] = [];
    }
    acc[item.section].push(item);
    return acc;
  }, {} as Record<string, typeof menuItems>);

  const drawer = (
    <div>
      <Toolbar>
        <Typography variant="h6" noWrap component="div">
          HR Mini
        </Typography>
      </Toolbar>
      <Divider />
      
      {/* Company Filter */}
      <Box sx={{ p: 2 }}>
        <Typography variant="subtitle2" color="text.secondary" sx={{ mb: 1 }}>
          🏢 Company Filter
        </Typography>
        <CompanyFilter
          value={selectedCompanyId}
          onChange={setSelectedCompanyId}
          showAllOption={true}
          label="Filter by Company"
          size="small"
        />
        {selectedCompany && (
          <Box sx={{ mt: 1 }}>
            <Alert severity="info" icon={<Business />}>
              <Typography variant="caption">
                <strong>Selected:</strong> {selectedCompany.legal_name}
                {selectedCompany.trade_name && ` (${selectedCompany.trade_name})`}
              </Typography>
            </Alert>
          </Box>
        )}
        {!selectedCompanyId && (
          <Box sx={{ mt: 1 }}>
            <Alert severity="success">
              <Typography variant="caption">
                <strong>All Companies</strong> - Showing data from all companies
              </Typography>
            </Alert>
          </Box>
        )}
      </Box>
      
      <Divider />
      
      {/* Navigation Menu */}
      {Object.entries(groupedItems).map(([section, items]) => (
        <div key={section}>
          <Box sx={{ px: 2, py: 1 }}>
            <Typography variant="subtitle2" color="text.secondary">
              {section}
            </Typography>
          </Box>
          <List>
            {items.map((item) => (
              <ListItem key={item.text} disablePadding>
                <ListItemButton
                  selected={location.pathname === item.path}
                  onClick={() => navigate(item.path)}
                >
                  <ListItemIcon>
                    {item.icon}
                  </ListItemIcon>
                  <ListItemText primary={item.text} />
                </ListItemButton>
              </ListItem>
            ))}
          </List>
          <Divider />
        </div>
      ))}
    </div>
  );

  return (
    <Box sx={{ display: 'flex' }}>
      <AppBar
        position="fixed"
        sx={{
          width: { sm: `calc(100% - ${drawerWidth}px)` },
          ml: { sm: `${drawerWidth}px` },
        }}
      >
        <Toolbar>
          <IconButton
            color="inherit"
            aria-label="open drawer"
            edge="start"
            onClick={handleDrawerToggle}
            sx={{ mr: 2, display: { sm: 'none' } }}
          >
            <MenuIcon />
          </IconButton>
          <Typography variant="h6" noWrap component="div" sx={{ flexGrow: 1 }}>
            HR Management System
          </Typography>
          <Box sx={{ display: 'flex', alignItems: 'center' }}>
            <Typography variant="body2" sx={{ mr: 2 }}>
              {user?.display_name || user?.username}
            </Typography>
            <IconButton
              size="large"
              aria-label="account of current user"
              aria-controls="menu-appbar"
              aria-haspopup="true"
              onClick={handleMenu}
              color="inherit"
            >
              <AccountCircle />
            </IconButton>
        <Menu
          id="menu-appbar"
          anchorEl={anchorEl}
          anchorOrigin={{
            vertical: 'top',
            horizontal: 'right',
          }}
          keepMounted
          transformOrigin={{
            vertical: 'top',
            horizontal: 'right',
          }}
          open={Boolean(anchorEl)}
          onClose={handleClose}
        >
          <MenuItem onClick={handleChangePassword}>Change My Password</MenuItem>
          <MenuItem onClick={handleLogout}>Logout</MenuItem>
        </Menu>
          </Box>
        </Toolbar>
      </AppBar>
      
      <Box
        component="nav"
        sx={{ width: { sm: drawerWidth }, flexShrink: { sm: 0 } }}
        aria-label="mailbox folders"
      >
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={handleDrawerToggle}
          ModalProps={{
            keepMounted: true,
          }}
          sx={{
            display: { xs: 'block', sm: 'none' },
            '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
          }}
        >
          {drawer}
        </Drawer>
        <Drawer
          variant="permanent"
          sx={{
            display: { xs: 'none', sm: 'block' },
            '& .MuiDrawer-paper': { boxSizing: 'border-box', width: drawerWidth },
          }}
          open
        >
          {drawer}
        </Drawer>
      </Box>
      
      <Box
        component="main"
        sx={{
          flexGrow: 1,
          p: 3,
          width: { sm: `calc(100% - ${drawerWidth}px)` },
        }}
      >
        <Toolbar />
        {children}
      </Box>
    </Box>
  );
};
