import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Paper,
  Alert,
  Grid,
  Card,
  CardContent,
  TextField,
  Button,
  Chip,
  Table,
  TableBody,
  TableCell,
  TableContainer,
  TableHead,
  TableRow,
  IconButton,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  FormControl,
  InputLabel,
  Select,
  MenuItem,
  Snackbar,
  CircularProgress,
  Stack,
  Tooltip,
  Tabs,
  Tab,
  CardHeader,
  Avatar,
  LinearProgress,
  Fade,
  alpha,
  useTheme,
} from '@mui/material';
import {
  Search as SearchIcon,
  Add,
  Edit,
  Delete,
  Event,
  Person,
  CheckCircle,
  Cancel,
  Warning,
  Info,
  BeachAccess,
  LocalHospital,
  MoreHoriz,
  Email as EmailIcon,
  Phone as PhoneIcon,
} from '@mui/icons-material';
import { useCompanyFilter } from '../hooks/useCompanyFilter';
import { useSelectedEmployee } from '../contexts/SelectedEmployeeContext';
import { apiClient } from '../api/client';

// Types
interface Employee {
  id: string;
  first_name: string;
  last_name: string;
  full_name: string;
  email?: string;
  phone?: string;
  hire_date?: string;
  probation_end_date?: string;
  status: string;
}

interface LeaveType {
  id: number;
  name: string;
  code: string;
  days_per_year: number;
  carry_over: boolean;
  max_carry_over?: number;
  is_active: boolean;
}

interface Leave {
  id: number;
  employee_id: string;
  leave_type_id: number;
  start_date: string;
  end_date: string;
  days_requested: number;
  reason?: string;
  status: string;
  approved_by?: number;
  approved_at?: string;
  remarks?: string;
  created_at: string;
  updated_at?: string;
  employee?: Employee;
}

interface LeaveBalance {
  employee_id: string;
  vacation_remaining: number;
  sick_remaining: number;
  vacation_entitlement: number;
  sick_entitlement: number;  // Added for proper sick leave display
  vacation_earned_date?: string;
  vacation_expiry_date?: string;
  hire_date?: string;
  seniority_start_date?: string;  // Added for transparency
  years_employed: number;
}

interface LeaveFormData {
  leave_type_id: number;
  start_date: string;
  end_date: string;
  days_requested: number;
  reason: string;
  status: string;
}

type LeaveCategory = 'all' | 'vacation' | 'sick' | 'others';

const LeavePage: React.FC = () => {
  const theme = useTheme();
  const { isFilterActive, getCompanyName, selectedCompanyId } = useCompanyFilter();
  const { selectedEmployee: globalSelectedEmployee, setSelectedEmployee: setGlobalSelectedEmployee } = useSelectedEmployee();
  
  // State
  const [leaveTypes, setLeaveTypes] = useState<LeaveType[]>([]);
  const [leaves, setLeaves] = useState<Leave[]>([]);
  const [leaveBalance, setLeaveBalance] = useState<LeaveBalance | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<string>('');
  const [selectedEmployeeData, setSelectedEmployeeData] = useState<Employee | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(false);
  
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [selectedCategory, setSelectedCategory] = useState<LeaveCategory>('all');
  
  // Employee search states - using EmployeePage pattern
  const [searchResults, setSearchResults] = useState<Employee[]>([]);
  
  // Dialog states
  const [addDialogOpen, setAddDialogOpen] = useState(false);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [selectedLeave, setSelectedLeave] = useState<Leave | null>(null);
  
  // Form state
  const [formData, setFormData] = useState<LeaveFormData>({
    leave_type_id: 0, // Will be set to first available leave type when loaded
    start_date: '',
    end_date: '',
    days_requested: 0,
    reason: '',
    status: 'Active',
  });

  // Data loading functions
  const loadLeaveTypes = useCallback(async () => {
    try {
      const response = await apiClient.get('/leaves/types');
      // The API returns the list directly, not wrapped in a data property
      const types = response.data;
      setLeaveTypes(types);
      
      // Set the first available leave type as default if form is not initialized
      if (types.length > 0 && formData.leave_type_id === 0) {
        setFormData(prev => ({ ...prev, leave_type_id: types[0].id }));
      }
    } catch (err) {
      setError('Failed to load leave types');
    }
  }, [formData.leave_type_id]);

  const loadLeaves = React.useCallback(async () => {
    try {
      // If searching, show search results instead of leave records
      if (searchTerm) {
        setLoading(true);
        // Search for employees matching the search term
        const employeeResponse = await apiClient.get('/employees/list', {
          params: { q: searchTerm, company_id: selectedCompanyId || undefined }
        });
        setSearchResults(employeeResponse.data?.data || []);
        setLeaves([]); // Don't show leave records yet
        setLoading(false);
        return;
      } else {
        // Only filter by employee if no search term is provided
        const employeeToFilter = globalSelectedEmployee?.id || selectedEmployee;
        
        if (employeeToFilter) {
          setLoading(true);
          const twoYearsAgo = new Date();
          twoYearsAgo.setFullYear(twoYearsAgo.getFullYear() - 2);
          const response = await apiClient.get('/leaves', {
            params: {
              employee_id: employeeToFilter,
              start_from: twoYearsAgo.toISOString().split('T')[0]
            }
          });
          setLeaves(response.data);
          setLoading(false);
        } else {
          // No employee selected and no search - just clear data, no loading needed
          setLeaves([]);
          setSearchResults([]);
        }
        
        // Clear search results when we have a selected employee (not from search)
        if (globalSelectedEmployee?.id || selectedEmployee) {
          setSearchResults([]);
        }
      }
    } catch (err: any) {
      console.error('Failed to load leaves:', err);
      setError(err.response?.data?.detail || 'Failed to load leave history');
      setLoading(false);
    }
  }, [searchTerm, selectedEmployee, globalSelectedEmployee?.id, selectedCompanyId]);

  const loadLeaveBalance = React.useCallback(async (employeeId?: string) => {
    const targetEmployeeId = employeeId || selectedEmployee;
    if (!targetEmployeeId) return;
    
    try {
      const response = await apiClient.get(`/leaves/balance/${targetEmployeeId}`);
      setLeaveBalance(response.data);
    } catch (err) {
      setError('Failed to load leave balance');
    }
  }, [selectedEmployee]);

  // Search functionality - using EmploymentPage pattern
  const handleSearch = () => {
    loadLeaves();
  };

  const handleSearchResultClick = async (employee: Employee) => {
    // Set the global selected employee first
    setGlobalSelectedEmployee({
      id: employee.id,
      first_name: employee.first_name,
      last_name: employee.last_name,
      full_name: employee.full_name,
      email: employee.email,
      phone: employee.phone,
      status: employee.status,
    });
    
    // Also update local states immediately
    setSelectedEmployee(employee.id);
    setSelectedEmployeeData(employee);
    
    // Load leave data for this employee first
    try {
      await loadLeaves();
      await loadLeaveBalance(employee.id); // Pass the employee ID directly
      
      // Only clear search states after data is successfully loaded
      // Add a small delay to ensure smooth transition
      setTimeout(() => {
        setSearchTerm('');
        setSearchResults([]);
      }, 100);
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to load leave data');
    }
  };


  // Load data
  useEffect(() => {
    loadLeaveTypes();
  }, [loadLeaveTypes]);

  // Auto-select employee from global context when component mounts or global employee changes
  useEffect(() => {
    if (globalSelectedEmployee) {
      // Update local states if global employee is different from current selection
      if (!selectedEmployee || selectedEmployee !== globalSelectedEmployee.id) {
        setSelectedEmployee(globalSelectedEmployee.id);
        setSelectedEmployeeData(globalSelectedEmployee);
        // Clear search states when employee is selected from global context
        setSearchTerm('');
        setSearchResults([]);
      }
    }
  }, [globalSelectedEmployee, selectedEmployee]);

  // Load data when dependencies change - using EmployeePage pattern
  useEffect(() => {
    // Only load if we have a search term or selected employee
    if (searchTerm || selectedEmployee || globalSelectedEmployee?.id) {
      loadLeaves();
    }
  }, [searchTerm, selectedEmployee, globalSelectedEmployee?.id, loadLeaves]);

  // Load leave balance when employee is selected
  useEffect(() => {
    if (selectedEmployee) {
      loadLeaveBalance();
    }
  }, [selectedEmployee, loadLeaveBalance]);

  // Helper functions for leave categorization
  const getLeaveTypeCategory = (leaveTypeCode: string): LeaveCategory => {
    switch (leaveTypeCode.toUpperCase()) {
      case 'VAC':
        return 'vacation';
      case 'SICK':
      case 'UNPAIDSICK':
        return 'sick';
      case 'UNPAID':
      default:
        return 'others';
    }
  };

  const getLeaveTypeById = (id: number) => {
    return leaveTypes.find(lt => lt.id === id);
  };


  // Filter leaves based on selected category
  const filteredLeaves = leaves.filter(leave => {
    if (selectedCategory === 'all') return true;
    
    const leaveType = getLeaveTypeById(leave.leave_type_id);
    if (!leaveType) return false;
    
    const category = getLeaveTypeCategory(leaveType.code);
    return category === selectedCategory;
  });

  // Calculate category statistics
  const getCategoryStats = (category: LeaveCategory) => {
    if (!leaveBalance || !selectedEmployee) return null;

    const categoryLeaves = leaves.filter(leave => {
      if (category === 'all') return true;
      const leaveType = getLeaveTypeById(leave.leave_type_id);
      if (!leaveType) return false;
      return getLeaveTypeCategory(leaveType.code) === category;
    });

    const taken = categoryLeaves
      .filter(leave => leave.status === 'Active')
      .reduce((sum, leave) => sum + leave.days_requested, 0);

    switch (category) {
      case 'vacation':
        return {
          entitlement: leaveBalance.vacation_entitlement,
          taken,
          balance: leaveBalance.vacation_remaining,
          color: 'primary'
        };
      case 'sick':
        return {
          entitlement: leaveBalance.sick_entitlement, // Use actual entitlement from API (0.0 if not eligible)
          taken,
          balance: leaveBalance.sick_remaining,
          color: 'secondary'
        };
      case 'others':
        return {
          entitlement: null,
          taken,
          balance: null,
          color: 'default'
        };
      default:
        return null;
    }
  };

  // Calculate days between dates
  const calculateDays = (startDate: string, endDate: string) => {
    const start = new Date(startDate);
    const end = new Date(endDate);
    const diffTime = Math.abs(end.getTime() - start.getTime());
    return Math.ceil(diffTime / (1000 * 60 * 60 * 24)) + 1;
  };

  // Format date to avoid timezone issues
  const formatDate = (dateString: string) => {
    // If the date string is in YYYY-MM-DD format, use it directly
    if (dateString.match(/^\d{4}-\d{2}-\d{2}$/)) {
      const [year, month, day] = dateString.split('-');
      return new Date(parseInt(year), parseInt(month) - 1, parseInt(day)).toLocaleDateString();
    }
    // Otherwise, parse as date and format
    const date = new Date(dateString);
    return date.toLocaleDateString();
  };

  // Handle form changes
  const handleFormChange = (field: keyof LeaveFormData, value: any) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    
    // Auto-calculate days when dates change
    if ((field === 'start_date' || field === 'end_date') && formData.start_date && formData.end_date) {
      const days = calculateDays(formData.start_date, formData.end_date);
      setFormData(prev => ({ ...prev, days_requested: days }));
    }
  };

  // Handle add leave
  const handleAddLeave = async () => {
    if (!selectedEmployee) return;
    
    try {
      setLoading(true);
      await apiClient.post('/leaves', {
        employee_id: selectedEmployee,
        ...formData,
      });
      
      setSuccess('Leave request created successfully');
      setAddDialogOpen(false);
      resetForm();
      loadLeaves();
      loadLeaveBalance();
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to create leave request');
    } finally {
      setLoading(false);
    }
  };

  // Handle edit leave
  const handleEditLeave = async () => {
    if (!selectedLeave) return;
    
    try {
      setLoading(true);
      await apiClient.put(`/leaves/${selectedLeave.id}`, formData);
      
      setSuccess('Leave request updated successfully');
      setEditDialogOpen(false);
      resetForm();
      loadLeaves();
      loadLeaveBalance();
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to update leave request');
    } finally {
      setLoading(false);
    }
  };

  // Handle delete leave
  const handleDeleteLeave = async () => {
    if (!selectedLeave) return;
    
    try {
      setLoading(true);
      await apiClient.delete(`/leaves/${selectedLeave.id}`);
      
      setSuccess('Leave request deleted successfully');
      setDeleteDialogOpen(false);
      loadLeaves();
      loadLeaveBalance();
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to delete leave request');
    } finally {
      setLoading(false);
    }
  };

  // Reset form
  const resetForm = () => {
    setFormData({
      leave_type_id: leaveTypes.length > 0 ? leaveTypes[0].id : 0,
      start_date: '',
      end_date: '',
      days_requested: 0,
      reason: '',
      status: 'Active',
    });
    setSelectedLeave(null);
  };

  // Open edit dialog
  const openEditDialog = (leave: Leave) => {
    setSelectedLeave(leave);
    setFormData({
      leave_type_id: leave.leave_type_id,
      start_date: leave.start_date,
      end_date: leave.end_date,
      days_requested: leave.days_requested,
      reason: leave.reason || '',
      status: leave.status,
    });
    setEditDialogOpen(true);
  };

  // Open delete dialog
  const openDeleteDialog = (leave: Leave) => {
    setSelectedLeave(leave);
    setDeleteDialogOpen(true);
  };

  // Get status color
  const getStatusColor = (status: string) => {
    switch (status.toLowerCase()) {
      case 'active':
        return 'success';
      case 'cancelled':
        return 'error';
      case 'pending':
        return 'warning';
      default:
        return 'default';
    }
  };

  // Get status icon
  const getStatusIcon = (status: string) => {
    switch (status.toLowerCase()) {
      case 'active':
        return <CheckCircle />;
      case 'cancelled':
        return <Cancel />;
      case 'pending':
        return <Warning />;
      default:
        return <Info />;
    }
  };

  return (
    <Box>
      <Box display="flex" justifyContent="space-between" alignItems="center" mb={3}>
      <Typography variant="h4" gutterBottom>
        Leave Dashboard
      </Typography>
        <Button
          variant="contained"
          startIcon={<Add />}
          onClick={() => setAddDialogOpen(true)}
          size="large"
        >
          Add Leave
        </Button>
      </Box>
      
      {/* Company Filter Indicator */}
      {isFilterActive && (
        <Alert severity="info" sx={{ mb: 3 }}>
          <Typography variant="body2">
            <strong>Company Filter Active:</strong> Showing leave data for {getCompanyName()} only.
          </Typography>
        </Alert>
      )}
      
      {/* Search and Filter Controls - copied from EmployeePage */}
      <Paper 
        sx={{ 
          p: 3, 
          mb: 3, 
          background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.05)} 0%, ${alpha(theme.palette.secondary.main, 0.05)} 100%)`,
          border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
        }}
      >
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap' }}>
          <TextField
            label="Search employees"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
            sx={{ 
              minWidth: 250,
              '& .MuiOutlinedInput-root': {
                backgroundColor: 'background.paper',
              }
            }}
            placeholder="Search by name, ID, email..."
          />
          <Button
            variant="contained"
            startIcon={<SearchIcon />}
            onClick={handleSearch}
            disabled={loading}
            sx={{
              px: 3,
              py: 1.5,
              fontWeight: 600,
              textTransform: 'none',
              borderRadius: 2,
            }}
          >
            Search
          </Button>
          <Button
            variant="outlined"
            onClick={() => {
              setSearchTerm('');
              loadLeaves();
            }}
            disabled={loading}
            sx={{
              px: 3,
              py: 1.5,
              fontWeight: 500,
              textTransform: 'none',
              borderRadius: 2,
            }}
          >
            Clear
          </Button>
        </Box>
      </Paper>

      {/* Employee Cards - copied from EmployeePage */}
      <Box sx={{ mt: 3 }}>
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
            <Typography>Loading employees...</Typography>
          </Box>
        ) : searchTerm && searchResults.length === 0 ? (
          <Paper sx={{ p: 4, textAlign: 'center' }}>
            <Typography variant="h6" color="text.secondary">
              No employees found
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              Try adjusting your search criteria.
            </Typography>
          </Paper>
        ) : searchResults.length > 0 ? (
          <Grid container spacing={3}>
            {searchResults.map((employee) => (
              <Grid item xs={12} sm={6} md={4} lg={3} key={employee.id}>
                <Fade in={true} timeout={300}>
                  <Card
                    sx={{
                      height: '100%',
                      display: 'flex',
                      flexDirection: 'column',
                      cursor: 'pointer',
                      transition: 'all 0.2s ease-in-out',
                      border: (globalSelectedEmployee?.id === employee.id) ? `2px solid ${theme.palette.primary.main}` : '1px solid',
                      borderColor: (globalSelectedEmployee?.id === employee.id) ? theme.palette.primary.main : 'divider',
                      '&:hover': {
                        transform: 'translateY(-4px)',
                        boxShadow: theme.shadows[8],
                        borderColor: theme.palette.primary.main,
                      },
                    }}
                    onClick={() => handleSearchResultClick(employee)}
                  >
                    <CardContent sx={{ flexGrow: 1, pb: 1 }}>
                      {/* Header with Avatar */}
                      <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', mb: 2 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                          <Avatar
                            sx={{
                              bgcolor: theme.palette.primary.main,
                              width: 48,
                              height: 48,
                              fontSize: '1.2rem',
                              fontWeight: 'bold',
                            }}
                          >
                            {employee.first_name?.[0]}{employee.last_name?.[0]}
                          </Avatar>
                          <Box>
                            <Typography variant="h6" component="div" sx={{ fontWeight: 600, lineHeight: 1.2 }}>
                              {employee.full_name}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                              ID: {employee.id}
                            </Typography>
                          </Box>
                        </Box>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <Chip
                            label={employee.status}
                            color="primary"
                            size="small"
                            sx={{ fontWeight: 500 }}
                          />
                        </Box>
                      </Box>

                      {/* Contact Information */}
                      <Box sx={{ mb: 2 }}>
                        {employee.email && (
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <EmailIcon sx={{ fontSize: 16, color: 'text.secondary' }} />
                            <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem' }}>
                              {employee.email}
                            </Typography>
                          </Box>
                        )}
                        {employee.phone && (
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <PhoneIcon sx={{ fontSize: 16, color: 'text.secondary' }} />
                            <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem' }}>
                              {employee.phone}
                            </Typography>
                          </Box>
                        )}
                      </Box>
                    </CardContent>
                  </Card>
                </Fade>
              </Grid>
            ))}
          </Grid>
        ) : null}
      </Box>

      {selectedEmployeeData ? (
        <>
          {/* Employee Info Header */}
          <Card sx={{ mb: 3 }}>
            <CardContent>
              <Box display="flex" alignItems="center" gap={2}>
                <Avatar sx={{ bgcolor: 'primary.main' }}>
                  <Person />
                </Avatar>
                <Box>
                  <Typography variant="h6">
                    {selectedEmployeeData.full_name}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    ID: {selectedEmployeeData.id} • 
                    {selectedEmployeeData.status}
                    {leaveBalance && ` • ${leaveBalance.years_employed.toFixed(1)} years employed`}
                  </Typography>
                </Box>
              </Box>
            </CardContent>
          </Card>

          {/* Leave Categories Tabs */}
          <Paper sx={{ mb: 3 }}>
            <Tabs
              value={selectedCategory}
              onChange={(_, newValue) => setSelectedCategory(newValue)}
              variant="fullWidth"
              sx={{ borderBottom: 1, borderColor: 'divider' }}
            >
              <Tab
                label="All Leave"
                value="all"
                icon={<Event />}
                iconPosition="start"
              />
              <Tab
                label="Vacation"
                value="vacation"
                icon={<BeachAccess />}
                iconPosition="start"
              />
              <Tab
                label="Sick Leave"
                value="sick"
                icon={<LocalHospital />}
                iconPosition="start"
              />
              <Tab
                label="Other Leave"
                value="others"
                icon={<MoreHoriz />}
                iconPosition="start"
              />
            </Tabs>
          </Paper>

          {/* Category Statistics Cards */}
          <Grid container spacing={3} sx={{ mb: 3 }}>
            {['vacation', 'sick', 'others'].map((category) => {
              const stats = getCategoryStats(category as LeaveCategory);
              if (!stats) return null;

              const categoryInfoMap = {
                vacation: { title: 'Vacation', icon: <BeachAccess />, color: 'primary' },
                sick: { title: 'Sick Leave', icon: <LocalHospital />, color: 'secondary' },
                others: { title: 'Other Leave', icon: <MoreHoriz />, color: 'default' }
              } as const;

              const categoryInfo = categoryInfoMap[category as keyof typeof categoryInfoMap];
              if (!categoryInfo) return null;

              return (
                <Grid item xs={12} md={4} key={category}>
                  <Card 
                    sx={{ 
                      height: '100%',
                      cursor: 'pointer',
                      border: selectedCategory === category ? 2 : 1,
                      borderColor: selectedCategory === category ? `${categoryInfo.color}.main` : 'divider',
                      '&:hover': { boxShadow: 3 }
                    }}
                    onClick={() => setSelectedCategory(category as LeaveCategory)}
                  >
                    <CardHeader
                      avatar={
                        <Avatar sx={{ bgcolor: `${categoryInfo.color}.main` }}>
                          {categoryInfo.icon}
                        </Avatar>
                      }
                      title={categoryInfo.title}
                      action={
                        selectedCategory === category && (
                          <Chip label="Selected" color={categoryInfo.color as any} size="small" />
                        )
                      }
                    />
                    <CardContent>
                      {stats.entitlement !== null ? (
                        <Box>
                          <Grid container spacing={2} textAlign="center">
                            <Grid item xs={4}>
                              <Typography variant="h6" color="text.secondary">
                                {stats.entitlement.toFixed(1)}
                              </Typography>
                              <Typography variant="caption" color="text.secondary">
                                Entitlement
                              </Typography>
                            </Grid>
                            <Grid item xs={4}>
                              <Typography variant="h6" color="warning.main">
                                {stats.taken.toFixed(1)}
                              </Typography>
                              <Typography variant="caption" color="text.secondary">
                                Taken
                              </Typography>
                            </Grid>
                            <Grid item xs={4}>
                              <Typography variant="h6" color={`${stats.color}.main`}>
                                {stats.balance?.toFixed(1) || 'N/A'}
                              </Typography>
                              <Typography variant="caption" color="text.secondary">
                                Balance
                              </Typography>
                            </Grid>
                          </Grid>
                          {stats.entitlement > 0 && (
                            <Box sx={{ mt: 2 }}>
                              <LinearProgress
                                variant="determinate"
                                value={(stats.taken / stats.entitlement) * 100}
                                color={stats.color as any}
                                sx={{ height: 8, borderRadius: 4 }}
                              />
                              <Typography variant="caption" color="text.secondary" sx={{ mt: 1, display: 'block' }}>
                                {((stats.taken / stats.entitlement) * 100).toFixed(1)}% used
                              </Typography>
                            </Box>
                          )}
                        </Box>
                      ) : (
                        <Box textAlign="center">
                          <Typography variant="h6" color="text.secondary">
                            {stats.taken.toFixed(1)}
                          </Typography>
                          <Typography variant="caption" color="text.secondary">
                            Days Taken
                          </Typography>
                        </Box>
                      )}
                    </CardContent>
                  </Card>
                </Grid>
              );
            })}
          </Grid>

          {/* Leave History */}
      <Paper sx={{ p: 3 }}>
            <Box display="flex" justifyContent="space-between" alignItems="center" mb={2}>
              <Typography variant="h6">
                Leave History
                {selectedCategory !== 'all' && (
                  <Chip 
                    label={`${selectedCategory.charAt(0).toUpperCase() + selectedCategory.slice(1)} Only`} 
                    size="small" 
                    sx={{ ml: 2 }} 
                  />
                )}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                {filteredLeaves.length} record{filteredLeaves.length !== 1 ? 's' : ''} found
              </Typography>
            </Box>

            {filteredLeaves.length === 0 ? (
              <Box textAlign="center" py={4}>
                <Event sx={{ fontSize: 48, color: 'text.secondary', mb: 2 }} />
                <Typography variant="body2" color="text.secondary">
                  No leave records found for this category
                </Typography>
              </Box>
            ) : (
              <TableContainer>
                <Table>
                  <TableHead>
                    <TableRow>
                      <TableCell>Leave Type</TableCell>
                      <TableCell>Dates</TableCell>
                      <TableCell>Days</TableCell>
                      <TableCell>Status</TableCell>
                      <TableCell>Reason</TableCell>
                      <TableCell>Actions</TableCell>
                    </TableRow>
                  </TableHead>
                  <TableBody>
                    {filteredLeaves.map((leave) => {
                      const leaveType = getLeaveTypeById(leave.leave_type_id);
                      return (
                        <TableRow key={leave.id} hover>
                          <TableCell>
                            <Box display="flex" alignItems="center" gap={1}>
                              {leaveType && (
                                <Chip
                                  label={leaveType.code}
                                  size="small"
                                  color={getLeaveTypeCategory(leaveType.code) === 'vacation' ? 'primary' : 
                                         getLeaveTypeCategory(leaveType.code) === 'sick' ? 'secondary' : 'default'}
                                />
                              )}
                              <Typography variant="body2">
                                {leaveType?.name || 'Unknown'}
                              </Typography>
                            </Box>
                          </TableCell>
                          <TableCell>
                            <Typography variant="body2">
                              {formatDate(leave.start_date)} - {formatDate(leave.end_date)}
                            </Typography>
                          </TableCell>
                          <TableCell>
                            <Typography variant="body2" fontWeight="medium">
                              {leave.days_requested}
        </Typography>
                          </TableCell>
                          <TableCell>
                            <Chip
                              icon={getStatusIcon(leave.status)}
                              label={leave.status}
                              color={getStatusColor(leave.status) as any}
                              size="small"
                            />
                          </TableCell>
                          <TableCell>
                            <Typography variant="body2" noWrap maxWidth={200}>
                              {leave.reason || '-'}
          </Typography>
                          </TableCell>
                          <TableCell>
                            <Stack direction="row" spacing={1}>
                              <Tooltip title="Edit">
                                <IconButton
                                  size="small"
                                  onClick={() => openEditDialog(leave)}
                                >
                                  <Edit />
                                </IconButton>
                              </Tooltip>
                              <Tooltip title="Delete">
                                <IconButton
                                  size="small"
                                  color="error"
                                  onClick={() => openDeleteDialog(leave)}
                                >
                                  <Delete />
                                </IconButton>
                              </Tooltip>
                            </Stack>
                          </TableCell>
                        </TableRow>
                      );
                    })}
                  </TableBody>
                </Table>
              </TableContainer>
        )}
      </Paper>
        </>
      ) : (
        <Paper sx={{ p: 4, textAlign: 'center' }}>
          <Event sx={{ fontSize: 64, color: 'text.secondary', mb: 2 }} />
          <Typography variant="h6" color="text.secondary" gutterBottom>
            Select an Employee
          </Typography>
          <Typography variant="body2" color="text.secondary">
            Use the search field above to find and select an employee to view their leave information.
          </Typography>
        </Paper>
      )}

      {/* Add Leave Dialog */}
      <Dialog open={addDialogOpen} onClose={() => setAddDialogOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Add Leave Request</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Leave Type</InputLabel>
                <Select
                  value={formData.leave_type_id}
                  onChange={(e) => handleFormChange('leave_type_id', e.target.value)}
                >
                  {leaveTypes.map((type) => (
                    <MenuItem key={type.id} value={type.id}>
                      {type.name} ({type.code})
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Status"
                value={formData.status}
                onChange={(e) => handleFormChange('status', e.target.value)}
                select
              >
                <MenuItem value="Active">Active</MenuItem>
                <MenuItem value="Cancelled">Cancelled</MenuItem>
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Start Date"
                type="date"
                value={formData.start_date}
                onChange={(e) => handleFormChange('start_date', e.target.value)}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="End Date"
                type="date"
                value={formData.end_date}
                onChange={(e) => handleFormChange('end_date', e.target.value)}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Days"
                type="number"
                value={formData.days_requested}
                onChange={(e) => handleFormChange('days_requested', parseFloat(e.target.value) || 0)}
                inputProps={{ min: 0, step: 0.5 }}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Reason/Note"
                multiline
                rows={3}
                value={formData.reason}
                onChange={(e) => handleFormChange('reason', e.target.value)}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setAddDialogOpen(false)}>Cancel</Button>
          <Button
            onClick={handleAddLeave}
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={20} /> : 'Add Leave'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Edit Leave Dialog */}
      <Dialog open={editDialogOpen} onClose={() => setEditDialogOpen(false)} maxWidth="md" fullWidth>
        <DialogTitle>Edit Leave Request</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Leave Type</InputLabel>
                <Select
                  value={formData.leave_type_id}
                  onChange={(e) => handleFormChange('leave_type_id', e.target.value)}
                >
                  {leaveTypes.map((type) => (
                    <MenuItem key={type.id} value={type.id}>
                      {type.name} ({type.code})
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Status"
                value={formData.status}
                onChange={(e) => handleFormChange('status', e.target.value)}
                select
              >
                <MenuItem value="Active">Active</MenuItem>
                <MenuItem value="Cancelled">Cancelled</MenuItem>
              </TextField>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Start Date"
                type="date"
                value={formData.start_date}
                onChange={(e) => handleFormChange('start_date', e.target.value)}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="End Date"
                type="date"
                value={formData.end_date}
                onChange={(e) => handleFormChange('end_date', e.target.value)}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Days"
                type="number"
                value={formData.days_requested}
                onChange={(e) => handleFormChange('days_requested', parseFloat(e.target.value) || 0)}
                inputProps={{ min: 0, step: 0.5 }}
              />
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Reason/Note"
                multiline
                rows={3}
                value={formData.reason}
                onChange={(e) => handleFormChange('reason', e.target.value)}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setEditDialogOpen(false)}>Cancel</Button>
          <Button
            onClick={handleEditLeave}
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={20} /> : 'Update Leave'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
        <DialogTitle>Delete Leave Request</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete this leave request? This action cannot be undone.
          </Typography>
          {selectedLeave && (
            <Box sx={{ mt: 2, p: 2, bgcolor: 'grey.100', borderRadius: 1 }}>
              <Typography variant="body2">
                <strong>Leave ID:</strong> {selectedLeave.id}
              </Typography>
              <Typography variant="body2">
                <strong>Dates:</strong> {formatDate(selectedLeave.start_date)} - {formatDate(selectedLeave.end_date)}
              </Typography>
              <Typography variant="body2">
                <strong>Days:</strong> {selectedLeave.days_requested}
              </Typography>
              <Typography variant="body2">
                <strong>Status:</strong> {selectedLeave.status}
              </Typography>
            </Box>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialogOpen(false)}>Cancel</Button>
          <Button
            onClick={handleDeleteLeave}
            color="error"
            variant="contained"
            disabled={loading}
          >
            {loading ? <CircularProgress size={20} /> : 'Delete'}
          </Button>
        </DialogActions>
      </Dialog>

      {/* Snackbars */}
      <Snackbar
        open={!!error}
        autoHideDuration={6000}
        onClose={() => setError(null)}
        message={error}
      />
      <Snackbar
        open={!!success}
        autoHideDuration={6000}
        onClose={() => setSuccess(null)}
        message={success}
      />
    </Box>
  );
};

export default LeavePage;
