import React, { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Typography,
  Button,
  TextField,
  Select,
  MenuItem,
  FormControl,
  InputLabel,
  Paper,
  Dialog,
  DialogTitle,
  DialogContent,
  DialogActions,
  Chip,
  Alert,
  Grid,
  Card,
  CardContent,
  CardActions,
  Avatar,
  IconButton,
  Menu,
  ListItemIcon,
  ListItemText,
  Divider,
  Fade,
  useTheme,
  alpha,
} from '@mui/material';
import {
  Add as AddIcon,
  Edit as EditIcon,
  Delete as DeleteIcon,
  Search as SearchIcon,
  MoreVert as MoreVertIcon,
  Email as EmailIcon,
  Phone as PhoneIcon,
  LocationOn as LocationIcon,
  Work as WorkIcon,
  CalendarToday as CalendarIcon,
  ContactPhone as EmergencyIcon,
} from '@mui/icons-material';
import { employeeAPI } from '../api/client';
import { useAuth } from '../contexts/AuthContext';
import { useSelectedEmployee } from '../contexts/SelectedEmployeeContext';
import { useCompanyFilter } from '../hooks/useCompanyFilter';

interface Employee {
  id: string;
  first_name: string;
  last_name: string;
  other_name?: string;
  full_name: string;
  email?: string;
  phone?: string;
  street?: string;
  city?: string;
  province?: string;
  postal_code?: string;
  dob?: string;
  sin?: string;
  drivers_license?: string;
  hire_date?: string;
  probation_end_date?: string;
  seniority_start_date?: string;
  status: string;
  remarks?: string;
  paystub: boolean;
  use_mailing_address: boolean;
  mailing_street?: string;
  mailing_city?: string;
  mailing_province?: string;
  mailing_postal_code?: string;
  emergency_contact_name?: string;
  emergency_contact_phone?: string;
  created_at?: string;
  updated_at?: string;
}

const EmployeePage: React.FC = () => {
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState('');
  const [statusFilter, setStatusFilter] = useState('All');
  const [deleteDialogOpen, setDeleteDialogOpen] = useState(false);
  const [employeeToDelete, setEmployeeToDelete] = useState<Employee | null>(null);
  const [editDialogOpen, setEditDialogOpen] = useState(false);
  const [editingEmployee, setEditingEmployee] = useState<Employee | null>(null);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(null);
  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
  const [formData, setFormData] = useState({
    first_name: '',
    last_name: '',
    other_name: '',
    email: '',
    phone: '',
    street: '',
    city: '',
    province: '',
    postal_code: '',
    dob: '',
    sin: '',
    drivers_license: '',
    hire_date: '',
    probation_end_date: '',
    seniority_start_date: '',
    status: 'Active',
    remarks: '',
    emergency_contact_name: '',
    emergency_contact_phone: '',
  });
  const [error, setError] = useState('');

  const { hasPermission } = useAuth();
  const { selectedEmployee: globalSelectedEmployee, setSelectedEmployee: setGlobalSelectedEmployee } = useSelectedEmployee();
  const { selectedCompanyId, isFilterActive, getCompanyName } = useCompanyFilter();
  const theme = useTheme();

  // Debug logging
  useEffect(() => {
    console.log('Company filter changed:', {
      selectedCompanyId,
      isFilterActive,
      companyName: getCompanyName()
    });
  }, [selectedCompanyId, isFilterActive, getCompanyName]);

  const loadEmployees = useCallback(async () => {
    try {
      setLoading(true);
      console.log('Loading employees with params:', { 
        q: searchTerm,
        company_id: selectedCompanyId || undefined
      });
      
      const response = await employeeAPI.list({ 
        q: searchTerm,
        company_id: selectedCompanyId || undefined
      });
      
      console.log('Employee API response:', response);
      
      // Check if response has success field (new format) or is direct array (old format)
      if (response.data && response.data.success && Array.isArray(response.data.data)) {
        console.log('Using new format, employees:', response.data.data.length);
        setEmployees(response.data.data);
      } else if (Array.isArray(response.data)) {
        console.log('Using old format, employees:', response.data.length);
        setEmployees(response.data);
      } else {
        console.log('No employees found, response format:', response.data);
        setEmployees([]);
      }
    } catch (err: any) {
      console.error('Error loading employees:', err);
      setError(err.response?.data?.detail || 'Failed to load employees');
      setEmployees([]);
    } finally {
      setLoading(false);
    }
  }, [searchTerm, selectedCompanyId]);

  useEffect(() => {
    loadEmployees();
  }, [loadEmployees]);

  const handleSearch = () => {
    loadEmployees();
  };

  const handleDeleteClick = (employee: Employee) => {
    setEmployeeToDelete(employee);
    setDeleteDialogOpen(true);
  };

  const handleDeleteConfirm = async () => {
    if (!employeeToDelete) return;

    try {
      await employeeAPI.delete(employeeToDelete.id);
      setEmployees(employees.filter(emp => emp.id !== employeeToDelete.id));
      setDeleteDialogOpen(false);
      setEmployeeToDelete(null);
    } catch (err: any) {
      setError(err.response?.data?.detail || 'Failed to delete employee');
    }
  };

  const handleEditClick = (employee: Employee) => {
    setEditingEmployee(employee);
    setFormData({
      first_name: employee.first_name,
      last_name: employee.last_name,
      other_name: employee.other_name || '',
      email: employee.email || '',
      phone: employee.phone || '',
      street: employee.street || '',
      city: employee.city || '',
      province: employee.province || '',
      postal_code: employee.postal_code || '',
      dob: employee.dob || '',
      sin: employee.sin || '',
      drivers_license: employee.drivers_license || '',
      hire_date: employee.hire_date || '',
      probation_end_date: employee.probation_end_date || '',
      seniority_start_date: employee.seniority_start_date || '',
      status: employee.status,
      remarks: employee.remarks || '',
      emergency_contact_name: employee.emergency_contact_name || '',
      emergency_contact_phone: employee.emergency_contact_phone || '',
    });
    setEditDialogOpen(true);
    setAnchorEl(null);
  };

  const handleMenuClick = (event: React.MouseEvent<HTMLElement>, employee: Employee) => {
    setAnchorEl(event.currentTarget);
    setSelectedEmployee(employee);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    setSelectedEmployee(null);
  };

  const handleCardClick = (employee: Employee) => {
    setSelectedEmployee(employee);
    // Set the global selected employee for cross-page functionality
    setGlobalSelectedEmployee({
      id: employee.id,
      first_name: employee.first_name,
      last_name: employee.last_name,
      full_name: employee.full_name,
      email: employee.email,
      phone: employee.phone,
      status: employee.status,
    });
  };

  const handleEditClose = () => {
    setEditDialogOpen(false);
    setEditingEmployee(null);
    setFormData({
      first_name: '',
      last_name: '',
      other_name: '',
      email: '',
      phone: '',
      street: '',
      city: '',
      province: '',
      postal_code: '',
      dob: '',
      sin: '',
      drivers_license: '',
      hire_date: '',
      probation_end_date: '',
      seniority_start_date: '',
      status: 'Active',
      remarks: '',
      emergency_contact_name: '',
      emergency_contact_phone: '',
    });
  };

  const handleEditSubmit = async () => {
    if (!editingEmployee) return;

    try {
      // Prepare data for API - convert empty strings to empty strings for clearable fields
      const submitData = {
        ...formData,
        // Keep empty strings for clearable fields, convert to null for date fields
        other_name: formData.other_name || "",
        email: formData.email || "",
        phone: formData.phone || "",
        street: formData.street || "",
        city: formData.city || "",
        province: formData.province || "",
        postal_code: formData.postal_code || "",
        dob: formData.dob || null,  // Date fields should be null when empty
        sin: formData.sin || "",
        drivers_license: formData.drivers_license || "",
        hire_date: formData.hire_date || null,  // Date fields should be null when empty
        probation_end_date: formData.probation_end_date || null,  // Date fields should be null when empty
        seniority_start_date: formData.seniority_start_date || null,  // Date fields should be null when empty
        remarks: formData.remarks || "",
        emergency_contact_name: formData.emergency_contact_name || "",
        emergency_contact_phone: formData.emergency_contact_phone || "",
      };

      await employeeAPI.update(editingEmployee.id, submitData);
      
      // Refresh the employee list
      await loadEmployees();
      handleEditClose();
    } catch (err: any) {
      console.error('Update error:', err.response?.data);
      if (err.response?.status === 422) {
        // Handle validation errors
        const validationErrors = err.response?.data?.errors || [];
        const errorMessages = validationErrors.map((error: any) => 
          `${error.loc?.join('.')}: ${error.msg}`
        ).join(', ');
        setError(`Validation error: ${errorMessages}`);
      } else {
        setError(err.response?.data?.detail || 'Failed to update employee');
      }
    }
  };

  const getStatusColor = (status: string) => {
    switch (status) {
      case 'Active':
        return 'success';
      case 'On Leave':
        return 'warning';
      case 'Terminated':
        return 'error';
      case 'Probation':
        return 'info';
      default:
        return 'default';
    }
  };

  const formatDate = (dateString?: string) => {
    if (!dateString) return 'N/A';
    // Parse the date string as local date to avoid timezone issues
    const [year, month, day] = dateString.split('-').map(Number);
    const date = new Date(year, month - 1, day);
    return date.toLocaleDateString();
  };

  const getInitials = (firstName: string, lastName: string) => {
    return `${firstName.charAt(0)}${lastName.charAt(0)}`.toUpperCase();
  };

  const filteredEmployees = employees.filter(emp => 
    statusFilter === 'All' || emp.status === statusFilter
  );

  const totalEmployees = employees.length;
  const activeEmployees = employees.filter(emp => emp.status === 'Active').length;
  const onLeaveEmployees = employees.filter(emp => emp.status === 'On Leave').length;

  return (
    <Box>
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" gutterBottom sx={{ fontWeight: 700, color: 'text.primary' }}>
          Employee Directory
        </Typography>
        <Typography variant="body1" color="text.secondary" sx={{ mb: 3 }}>
          Manage and view all employee information in your organization
        </Typography>
        
        {/* Company Filter Indicator */}
        {isFilterActive && (
          <Paper 
            sx={{ 
              p: 2, 
              mb: 3, 
              background: `linear-gradient(135deg, ${alpha(theme.palette.info.main, 0.1)} 0%, ${alpha(theme.palette.info.main, 0.05)} 100%)`,
              border: `1px solid ${theme.palette.info.main}`,
              borderRadius: 2,
            }}
          >
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <WorkIcon sx={{ color: 'info.main', fontSize: 32 }} />
                <Box>
                  <Typography variant="h6" sx={{ fontWeight: 600, color: 'info.main' }}>
                    Company Filter Active: {getCompanyName()}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Showing employees from selected company only
                  </Typography>
                </Box>
              </Box>
            </Box>
          </Paper>
        )}

        {/* Global Selection Indicator */}
        {globalSelectedEmployee && (
          <Paper 
            sx={{ 
              p: 2, 
              mb: 3, 
              background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.1)} 0%, ${alpha(theme.palette.primary.main, 0.05)} 100%)`,
              border: `1px solid ${theme.palette.primary.main}`,
              borderRadius: 2,
            }}
          >
            <Box sx={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <Avatar
                  sx={{
                    bgcolor: theme.palette.primary.main,
                    width: 40,
                    height: 40,
                    fontSize: '1rem',
                    fontWeight: 'bold',
                  }}
                >
                  {getInitials(globalSelectedEmployee.first_name, globalSelectedEmployee.last_name)}
                </Avatar>
                <Box>
                  <Typography variant="h6" sx={{ fontWeight: 600, color: 'primary.main' }}>
                    {globalSelectedEmployee.full_name}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Currently selected for cross-page operations
                  </Typography>
                </Box>
              </Box>
              <Button
                variant="outlined"
                size="small"
                onClick={() => setGlobalSelectedEmployee(null)}
                sx={{ textTransform: 'none' }}
              >
                Clear Selection
              </Button>
            </Box>
          </Paper>
        )}
        
        {/* Statistics Cards */}
        <Grid container spacing={2} sx={{ mb: 3 }}>
          <Grid item xs={12} sm={6} md={3}>
            <Paper sx={{ p: 2, textAlign: 'center', background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.1)} 0%, ${alpha(theme.palette.primary.main, 0.05)} 100%)` }}>
              <Typography variant="h4" color="primary" sx={{ fontWeight: 700 }}>
                {totalEmployees}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Total Employees
              </Typography>
            </Paper>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Paper sx={{ p: 2, textAlign: 'center', background: `linear-gradient(135deg, ${alpha(theme.palette.success.main, 0.1)} 0%, ${alpha(theme.palette.success.main, 0.05)} 100%)` }}>
              <Typography variant="h4" color="success.main" sx={{ fontWeight: 700 }}>
                {activeEmployees}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Active
              </Typography>
            </Paper>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Paper sx={{ p: 2, textAlign: 'center', background: `linear-gradient(135deg, ${alpha(theme.palette.warning.main, 0.1)} 0%, ${alpha(theme.palette.warning.main, 0.05)} 100%)` }}>
              <Typography variant="h4" color="warning.main" sx={{ fontWeight: 700 }}>
                {onLeaveEmployees}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                On Leave
              </Typography>
            </Paper>
          </Grid>
          <Grid item xs={12} sm={6} md={3}>
            <Paper sx={{ p: 2, textAlign: 'center', background: `linear-gradient(135deg, ${alpha(theme.palette.info.main, 0.1)} 0%, ${alpha(theme.palette.info.main, 0.05)} 100%)` }}>
              <Typography variant="h4" color="info.main" sx={{ fontWeight: 700 }}>
                {totalEmployees - activeEmployees - onLeaveEmployees}
              </Typography>
              <Typography variant="body2" color="text.secondary">
                Other Status
              </Typography>
            </Paper>
          </Grid>
        </Grid>
      </Box>

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError('')}>
          {error}
        </Alert>
      )}

      {/* Search and Filter Controls */}
      <Paper 
        sx={{ 
          p: 3, 
          mb: 3, 
          background: `linear-gradient(135deg, ${alpha(theme.palette.primary.main, 0.05)} 0%, ${alpha(theme.palette.secondary.main, 0.05)} 100%)`,
          border: `1px solid ${alpha(theme.palette.primary.main, 0.1)}`,
        }}
      >
        <Box sx={{ display: 'flex', gap: 2, alignItems: 'center', flexWrap: 'wrap' }}>
          <TextField
            label="Search employees"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            onKeyPress={(e) => e.key === 'Enter' && handleSearch()}
            sx={{ 
              minWidth: 250,
              '& .MuiOutlinedInput-root': {
                backgroundColor: 'background.paper',
              }
            }}
            placeholder="Search by name, ID, email..."
          />
          <FormControl sx={{ minWidth: 180 }}>
            <InputLabel>Status Filter</InputLabel>
            <Select
              value={statusFilter}
              label="Status Filter"
              onChange={(e) => setStatusFilter(e.target.value)}
              sx={{
                backgroundColor: 'background.paper',
              }}
            >
              <MenuItem value="All">All Employees</MenuItem>
              <MenuItem value="Active">Active</MenuItem>
              <MenuItem value="On Leave">On Leave</MenuItem>
              <MenuItem value="Terminated">Terminated</MenuItem>
              <MenuItem value="Probation">Probation</MenuItem>
            </Select>
          </FormControl>
          <Button
            variant="contained"
            startIcon={<SearchIcon />}
            onClick={handleSearch}
            disabled={loading}
            sx={{
              px: 3,
              py: 1.5,
              fontWeight: 600,
              textTransform: 'none',
              borderRadius: 2,
            }}
          >
            Search
          </Button>
          <Button
            variant="outlined"
            onClick={() => {
              setSearchTerm('');
              setStatusFilter('All');
              loadEmployees();
            }}
            disabled={loading}
            sx={{
              px: 3,
              py: 1.5,
              fontWeight: 500,
              textTransform: 'none',
              borderRadius: 2,
            }}
          >
            Clear
          </Button>
          {hasPermission('employee:create') && (
            <Button
              variant="contained"
              startIcon={<AddIcon />}
              onClick={() => {
                // TODO: Open create dialog
              }}
              sx={{ 
                ml: 'auto',
                px: 3,
                py: 1.5,
                fontWeight: 600,
                textTransform: 'none',
                borderRadius: 2,
                background: `linear-gradient(45deg, ${theme.palette.primary.main} 30%, ${theme.palette.secondary.main} 90%)`,
                '&:hover': {
                  background: `linear-gradient(45deg, ${theme.palette.primary.dark} 30%, ${theme.palette.secondary.dark} 90%)`,
                }
              }}
            >
              Create Employee
            </Button>
          )}
        </Box>
      </Paper>

      {/* Employee Cards */}
      <Box sx={{ mt: 3 }}>
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', p: 4 }}>
            <Typography>Loading employees...</Typography>
          </Box>
        ) : filteredEmployees.length === 0 ? (
          <Paper sx={{ p: 4, textAlign: 'center' }}>
            <Typography variant="h6" color="text.secondary">
              No employees found
            </Typography>
            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
              Try adjusting your search criteria or create a new employee.
            </Typography>
          </Paper>
        ) : (
          <Grid container spacing={3}>
            {filteredEmployees.map((employee) => (
              <Grid item xs={12} sm={6} md={4} lg={3} key={employee.id}>
                <Fade in={true} timeout={300}>
                  <Card
                    sx={{
                      height: '100%',
                      display: 'flex',
                      flexDirection: 'column',
                      cursor: 'pointer',
                      transition: 'all 0.2s ease-in-out',
                      border: (selectedEmployee?.id === employee.id || globalSelectedEmployee?.id === employee.id) ? `2px solid ${theme.palette.primary.main}` : '1px solid',
                      borderColor: (selectedEmployee?.id === employee.id || globalSelectedEmployee?.id === employee.id) ? theme.palette.primary.main : 'divider',
                      '&:hover': {
                        transform: 'translateY(-4px)',
                        boxShadow: theme.shadows[8],
                        borderColor: theme.palette.primary.main,
                      },
                    }}
                    onClick={() => handleCardClick(employee)}
                  >
                    <CardContent sx={{ flexGrow: 1, pb: 1 }}>
                      {/* Header with Avatar and Actions */}
                      <Box sx={{ display: 'flex', alignItems: 'flex-start', justifyContent: 'space-between', mb: 2 }}>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                          <Avatar
                            sx={{
                              bgcolor: theme.palette.primary.main,
                              width: 48,
                              height: 48,
                              fontSize: '1.2rem',
                              fontWeight: 'bold',
                            }}
                          >
                            {getInitials(employee.first_name, employee.last_name)}
                          </Avatar>
                          <Box>
                            <Typography variant="h6" component="div" sx={{ fontWeight: 600, lineHeight: 1.2 }}>
                              {employee.full_name}
                            </Typography>
                            <Typography variant="body2" color="text.secondary">
                              ID: {employee.id}
                            </Typography>
                          </Box>
                        </Box>
                        <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                          <Chip
                            label={employee.status}
                            color={getStatusColor(employee.status) as any}
                            size="small"
                            sx={{ fontWeight: 500 }}
                          />
                          <IconButton
                            size="small"
                            onClick={(e) => {
                              e.stopPropagation();
                              handleMenuClick(e, employee);
                            }}
                            sx={{
                              opacity: 0.7,
                              '&:hover': { opacity: 1 },
                            }}
                          >
                            <MoreVertIcon />
                          </IconButton>
                        </Box>
                      </Box>

                      {/* Contact Information */}
                      <Box sx={{ mb: 2 }}>
                        {employee.email && (
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <EmailIcon sx={{ fontSize: 16, color: 'text.secondary' }} />
                            <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem' }}>
                              {employee.email}
                            </Typography>
                          </Box>
                        )}
                        {employee.phone && (
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <PhoneIcon sx={{ fontSize: 16, color: 'text.secondary' }} />
                            <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem' }}>
                              {employee.phone}
                            </Typography>
                          </Box>
                        )}
                        {(employee.city || employee.province) && (
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <LocationIcon sx={{ fontSize: 16, color: 'text.secondary' }} />
                            <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem' }}>
                              {[employee.city, employee.province].filter(Boolean).join(', ')}
                            </Typography>
                          </Box>
                        )}
                      </Box>

                      {/* Employment Information */}
                      <Box sx={{ mb: 2 }}>
                        {employee.hire_date && (
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <WorkIcon sx={{ fontSize: 16, color: 'text.secondary' }} />
                            <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem' }}>
                              Hired: {formatDate(employee.hire_date)}
                            </Typography>
                          </Box>
                        )}
                        {employee.dob && (
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <CalendarIcon sx={{ fontSize: 16, color: 'text.secondary' }} />
                            <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem' }}>
                              DOB: {formatDate(employee.dob)}
                            </Typography>
                          </Box>
                        )}
                      </Box>

                      {/* Emergency Contact */}
                      {employee.emergency_contact_name && (
                        <Box sx={{ 
                          p: 1.5, 
                          bgcolor: alpha(theme.palette.warning.main, 0.1),
                          borderRadius: 1,
                          border: `1px solid ${alpha(theme.palette.warning.main, 0.2)}`,
                        }}>
                          <Box sx={{ display: 'flex', alignItems: 'center', gap: 1, mb: 0.5 }}>
                            <EmergencyIcon sx={{ fontSize: 16, color: 'warning.main' }} />
                            <Typography variant="body2" sx={{ fontWeight: 500, color: 'warning.dark' }}>
                              Emergency Contact
                            </Typography>
                          </Box>
                          <Typography variant="body2" color="text.secondary" sx={{ fontSize: '0.875rem', ml: 3 }}>
                            {employee.emergency_contact_name}
                            {employee.emergency_contact_phone && ` • ${employee.emergency_contact_phone}`}
                          </Typography>
                        </Box>
                      )}
                    </CardContent>

                    {/* Card Actions */}
                    <CardActions sx={{ pt: 0, px: 2, pb: 2 }}>
                      <Button
                        size="small"
                        startIcon={<EditIcon />}
                        onClick={(e) => {
                          e.stopPropagation();
                          handleEditClick(employee);
                        }}
                        disabled={!hasPermission('employee:update')}
                        sx={{ 
                          textTransform: 'none',
                          fontWeight: 500,
                        }}
                      >
                        Edit
                      </Button>
                      <Button
                        size="small"
                        startIcon={<DeleteIcon />}
                        color="error"
                        onClick={(e) => {
                          e.stopPropagation();
                          handleDeleteClick(employee);
                        }}
                        disabled={!hasPermission('employee:delete')}
                        sx={{ 
                          textTransform: 'none',
                          fontWeight: 500,
                        }}
                      >
                        Delete
                      </Button>
                    </CardActions>
                  </Card>
                </Fade>
              </Grid>
            ))}
          </Grid>
        )}
      </Box>

      {/* Context Menu */}
      <Menu
        anchorEl={anchorEl}
        open={Boolean(anchorEl)}
        onClose={handleMenuClose}
        PaperProps={{
          sx: {
            minWidth: 160,
            boxShadow: theme.shadows[8],
          },
        }}
      >
        <MenuItem
          onClick={() => {
            if (selectedEmployee) {
              handleEditClick(selectedEmployee);
            }
          }}
          disabled={!hasPermission('employee:update')}
        >
          <ListItemIcon>
            <EditIcon fontSize="small" />
          </ListItemIcon>
          <ListItemText>Edit Employee</ListItemText>
        </MenuItem>
        <Divider />
        <MenuItem
          onClick={() => {
            if (selectedEmployee) {
              handleDeleteClick(selectedEmployee);
            }
          }}
          disabled={!hasPermission('employee:delete')}
          sx={{ color: 'error.main' }}
        >
          <ListItemIcon>
            <DeleteIcon fontSize="small" color="error" />
          </ListItemIcon>
          <ListItemText>Delete Employee</ListItemText>
        </MenuItem>
      </Menu>

      {/* Delete Confirmation Dialog */}
      <Dialog open={deleteDialogOpen} onClose={() => setDeleteDialogOpen(false)}>
        <DialogTitle>Delete Employee</DialogTitle>
        <DialogContent>
          <Typography>
            Are you sure you want to delete employee {employeeToDelete?.full_name}?
            This action cannot be undone.
          </Typography>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setDeleteDialogOpen(false)}>Cancel</Button>
          <Button onClick={handleDeleteConfirm} color="error" variant="contained">
            Delete
          </Button>
        </DialogActions>
      </Dialog>

      {/* Edit Employee Dialog */}
      <Dialog open={editDialogOpen} onClose={handleEditClose} maxWidth="lg" fullWidth>
        <DialogTitle>Edit Employee</DialogTitle>
        <DialogContent>
          <Grid container spacing={2} sx={{ mt: 1 }}>
            {/* Personal Information */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom>Personal Information</Typography>
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="First Name"
                value={formData.first_name}
                onChange={(e) => setFormData({ ...formData, first_name: e.target.value })}
                required
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Last Name"
                value={formData.last_name}
                onChange={(e) => setFormData({ ...formData, last_name: e.target.value })}
                required
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Other Name"
                value={formData.other_name}
                onChange={(e) => setFormData({ ...formData, other_name: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Email"
                type="email"
                value={formData.email}
                onChange={(e) => setFormData({ ...formData, email: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Phone"
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Date of Birth"
                type="date"
                value={formData.dob}
                onChange={(e) => setFormData({ ...formData, dob: e.target.value })}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="SIN"
                value={formData.sin}
                onChange={(e) => setFormData({ ...formData, sin: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Driver's License"
                value={formData.drivers_license}
                onChange={(e) => setFormData({ ...formData, drivers_license: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <FormControl fullWidth>
                <InputLabel>Status</InputLabel>
                <Select
                  value={formData.status}
                  label="Status"
                  onChange={(e) => setFormData({ ...formData, status: e.target.value })}
                >
                  <MenuItem value="Active">Active</MenuItem>
                  <MenuItem value="On Leave">On Leave</MenuItem>
                  <MenuItem value="Terminated">Terminated</MenuItem>
                  <MenuItem value="Probation">Probation</MenuItem>
                </Select>
              </FormControl>
            </Grid>

            {/* Address Information */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>Address Information</Typography>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Street Address"
                value={formData.street}
                onChange={(e) => setFormData({ ...formData, street: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="City"
                value={formData.city}
                onChange={(e) => setFormData({ ...formData, city: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Province"
                value={formData.province}
                onChange={(e) => setFormData({ ...formData, province: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Postal Code"
                value={formData.postal_code}
                onChange={(e) => setFormData({ ...formData, postal_code: e.target.value })}
              />
            </Grid>

            {/* Employment Information */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>Employment Information</Typography>
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Hire Date"
                type="date"
                value={formData.hire_date}
                onChange={(e) => setFormData({ ...formData, hire_date: e.target.value })}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Probation End Date"
                type="date"
                value={formData.probation_end_date}
                onChange={(e) => setFormData({ ...formData, probation_end_date: e.target.value })}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>
            <Grid item xs={12} sm={4}>
              <TextField
                fullWidth
                label="Seniority Start Date"
                type="date"
                value={formData.seniority_start_date}
                onChange={(e) => setFormData({ ...formData, seniority_start_date: e.target.value })}
                InputLabelProps={{ shrink: true }}
              />
            </Grid>

            {/* Emergency Contact */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>Emergency Contact</Typography>
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Emergency Contact Name"
                value={formData.emergency_contact_name}
                onChange={(e) => setFormData({ ...formData, emergency_contact_name: e.target.value })}
              />
            </Grid>
            <Grid item xs={12} sm={6}>
              <TextField
                fullWidth
                label="Emergency Contact Phone"
                value={formData.emergency_contact_phone}
                onChange={(e) => setFormData({ ...formData, emergency_contact_phone: e.target.value })}
              />
            </Grid>

            {/* Additional Information */}
            <Grid item xs={12}>
              <Typography variant="h6" gutterBottom sx={{ mt: 2 }}>Additional Information</Typography>
            </Grid>
            <Grid item xs={12}>
              <TextField
                fullWidth
                label="Remarks"
                multiline
                rows={3}
                value={formData.remarks}
                onChange={(e) => setFormData({ ...formData, remarks: e.target.value })}
              />
            </Grid>
          </Grid>
        </DialogContent>
        <DialogActions>
          <Button onClick={handleEditClose}>Cancel</Button>
          <Button onClick={handleEditSubmit} variant="contained">
            Save Changes
          </Button>
        </DialogActions>
      </Dialog>
    </Box>
  );
};

export default EmployeePage;
